import { DomainError } from "./DomainError";
import { OrderLine } from "./OrderLine";
import { FulfilmentState, OrderState, isCancellable, nextState } from "./OrderState";

export class Order {
  private currentState: OrderState = "placed";
  private readonly orderLines: readonly OrderLine[];

  private constructor(
    readonly id: string,
    lines: readonly OrderLine[],
  ) {
    this.orderLines = lines;
  }

  static place(id: string, lines: readonly OrderLine[]): Order {
    if (lines.length === 0) {
      throw new DomainError("invalid", "An order needs at least one line");
    }
    return new Order(id, Order.mergeLines(lines));
  }

  get state(): OrderState {
    return this.currentState;
  }

  get lines(): readonly OrderLine[] {
    return this.orderLines;
  }

  advanceTo(target: FulfilmentState): void {
    if (nextState(this.currentState) !== target) {
      throw new DomainError(
        "conflict",
        `Order ${this.id} cannot move from ${this.currentState} to ${target}`,
      );
    }
    this.currentState = target;
  }

  cancel(): void {
    if (!isCancellable(this.currentState)) {
      throw new DomainError("conflict", `Order ${this.id} is ${this.currentState} and cannot be cancelled`);
    }
    this.currentState = "cancelled";
  }

  private static mergeLines(lines: readonly OrderLine[]): OrderLine[] {
    const totals = new Map<string, number>();
    for (const line of lines) {
      totals.set(line.productId, (totals.get(line.productId) ?? 0) + line.quantity);
    }
    return [...totals].map(([productId, quantity]) => ({ productId, quantity }));
  }
}

